<script setup>
import { computed } from 'vue'
const props=defineProps({metrics:{type:Array,default:()=>[]},title:{type:String,default:'Role peer profile'},sample:{type:Number,default:0}})
const visible=computed(()=>props.metrics.filter(row=>Number.isFinite(Number(row.percentile))))
</script>
<template><section class="percentile-profile"><header><div><span class="eyebrow">PEER PERCENTILES</span><h2>{{title}}</h2></div><small>{{sample}} COMPARABLE PLAYERS</small></header><div v-if="visible.length" class="bars"><article v-for="metric in visible" :key="metric.key||metric.label" :title="metric.definition"><div><b>{{metric.label}}</b><span>{{metric.value}}</span></div><div class="track"><i :style="{width:`${Math.max(2,metric.percentile)}%`}"></i><em>{{metric.percentile}}</em></div><small>{{metric.definition}}</small></article></div><div v-else class="empty">No statistically comparable peer group is available.</div></section></template>
<style scoped>.percentile-profile{border:1px solid var(--line);background:var(--surface)}header{min-height:92px;padding:18px 20px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line)}h2{margin:5px 0 0;font-size:27px;letter-spacing:-.04em}header>small{font:700 7px 'DM Mono';color:var(--muted)}.bars{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1px;background:var(--line)}article{min-height:137px;padding:17px;background:var(--surface);display:grid;align-content:start;gap:10px}article>div:first-child{display:flex;justify-content:space-between;gap:10px}article b{font-size:11px}article span{font:800 12px 'DM Mono';color:var(--sport,var(--accent))}.track{height:25px;position:relative;background:var(--raised);overflow:hidden}.track i{position:absolute;inset:0 auto 0 0;background:linear-gradient(90deg,color-mix(in srgb,var(--sport,var(--accent)) 28%,transparent),var(--sport,var(--accent)));transform-origin:left;animation:grow .8s cubic-bezier(.2,.8,.2,1)}.track em{position:absolute;right:7px;top:50%;transform:translateY(-50%);font:800 8px 'DM Mono';font-style:normal;color:var(--text);mix-blend-mode:difference}article small{font-size:7px;line-height:1.45;color:var(--muted)}.empty{padding:42px;text-align:center;color:var(--muted);font-size:9px}@keyframes grow{from{transform:scaleX(0)}}@media(max-width:620px){header{align-items:flex-start;gap:10px}.bars{grid-template-columns:1fr}}@media(prefers-reduced-motion:reduce){.track i{animation:none}}</style>
